package scriptchecktest

import (
	"emon/ocr"
	"emon/plan"
	"emon/port"
	"emon/scriptcheck"
	"testing"
)

func skAnswer(ans *port.Cells, id int32, n int32, script int32, sconf int32, lang int32, lang0 int32) int32 {
	// An OCR answer of `n` words, one a line, each read in the language cell `lang` (the first in `lang0`), whose page OSD says is in `script` at the confidence `sconf`.
	var at int32 = plan.AnOcr(ans, id)
	var k int32 = 0
	var word int32 = 0
	for k < n {
		word = plan.AnOcrWord(ans, at, 10, 20+(k*60), 60, 40, 760, k, 0)
		plan.AnOcrCp(ans, word, 72)
		plan.AnOcrCp(ans, word, 105)
		k += 1
	}
	ocr.OxBegin(ans, 0, 0, 0, 0, 0, script, sconf, 500, n, 1, 0, 0, 0)
	k = 0
	for k < n {
		ocr.OxLine(ans, 10, 20+(k*60), 60, 40, 10, 55+(k*60), 70, 55+(k*60), 0, 0, 0, 20, 14, 6)
		k += 1
	}
	ocr.OxBlock(ans, 10, 20, 60, n*60, 0, 0, 0)
	k = 0
	for k < n {
		if k == 0 {
			ocr.OxWord(ans, 0, lang0, -1, 0)
		} else {
			ocr.OxWord(ans, 0, lang, -1, 0)
		}
		k += 1
	}
	plan.AnOcrEnd(ans, at)
	return at
}

func unreadOf(n int32, script int32, sconf int32, lang int32, lang0 int32) int32 {
	var ans *port.Cells = port.NewCells()
	var at int32 = skAnswer(ans, 272, n, script, sconf, lang, lang0)
	return scriptcheck.SkUnread(ans, at, port.NewCells())
}

func TestALanguageCellUnpacksToItsLetters(emonT *testing.T) {
	var out *port.Cells = port.NewCells()
	port.AssertEq(emonT, scriptcheck.SkUnpack(1701734144, out), 3, "`eng` is three letters")
	port.AssertEq(emonT, port.CellsAt(out, 0), 101, "e")
	port.AssertEq(emonT, port.CellsAt(out, 2), 103, "g")
	port.AssertEq(emonT, scriptcheck.SkUnpack(0, out), 0, "none")
}

func TestAScriptNoModelReadIsUnread(emonT *testing.T) {
	// Deva 1147500129, Latn 1281455214, Cyrl 1132032620; the languages `eng` 1701734144, `hin` 1751739904, `rus` 1920299776
	port.AssertEq(emonT, unreadOf(5, 1147500129, 629, 1701734144, 1701734144), 1, "a Devanagari page (OSD 62.9) read by `eng`: unread (the smoke review's Hindi scan)")
	port.AssertEq(emonT, unreadOf(5, 1132032620, 400, 1701734144, 1701734144), 1, "a Cyrillic page read by `eng`: unread")
	port.AssertEq(emonT, unreadOf(5, 1147500129, 629, 1751739904, 1751739904), 0, "the same read by `hin`, which reads Devanagari: read")
	port.AssertEq(emonT, unreadOf(5, 1147500129, 629, 1701734144, 1751739904), 0, "one word read by `hin` is a model that reads it: read")
	port.AssertEq(emonT, unreadOf(5, 1132032620, 400, 1920299776, 1920299776), 0, "a Cyrillic page read by `rus`: read")
	port.AssertEq(emonT, unreadOf(5, 1147500129, 629, 1920299776, 1920299776), 1, "a Devanagari page read by `rus` (which reads Cyrillic): unread")
}

func TestAPageTheEngineCanReadOrOsdIsUnsureOfIsNotFlagged(emonT *testing.T) {
	port.AssertEq(emonT, unreadOf(5, 1281455214, 629, 1701734144, 1701734144), 0, "a Latin page")
	port.AssertEq(emonT, unreadOf(5, 1147500129, 100, 1701734144, 1701734144), 0, "OSD unsure (confidence 10: a Latin page reads that)")
	port.AssertEq(emonT, unreadOf(5, 1147500129, scriptcheck.SkMinConf()-1, 1701734144, 1701734144), 0, "just under the bound")
	port.AssertEq(emonT, unreadOf(5, 1147500129, scriptcheck.SkMinConf(), 1701734144, 1701734144), 1, "at it")
	port.AssertEq(emonT, unreadOf(2, 1147500129, 629, 1701734144, 1701734144), 0, "two words: the engine read nothing of it to speak of")
	port.AssertEq(emonT, unreadOf(5, 0, 629, 1701734144, 1701734144), 0, "no script")
}

func TestAnAnswerWithNoExtensionIsNotFlagged(emonT *testing.T) {
	var ans *port.Cells = port.NewCells()
	var at int32 = plan.AnOcr(ans, 272)
	var w int32 = plan.AnOcrWord(ans, at, 10, 20, 60, 40, 760, 0, 0)
	plan.AnOcrCp(ans, w, 72)
	plan.AnOcrEnd(ans, at)
	port.AssertEq(emonT, scriptcheck.SkUnread(ans, at, port.NewCells()), 0, "an engine that says nothing of the script")
}
